Object.Field:
# Validating KM options
<%

/* Validate COMPATIBLE */
if (!(
	"7".equals( odiRef.getOption ("COMPATIBLE") )  ||
	"8".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"9".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"10".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"11".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"12".equals( odiRef.getOption ("COMPATIBLE") )
))  {
	%>raise OdiKMException("ODIKM-STDKM-10000", "ODIKM-STDKM-10000: Invalid value \"{0}\" for option \"COMPATIBLE\"",["<%=odiRef.getOption ("COMPATIBLE")%>"])<%
};

%>

declare
    v0 NUMBER;
    v1 NUMBER;
begin
    select
        case when upper(name) = 'COMPATIBLE' then to_number(substr(value, 1, instr(value, '.',1,1)-1)) else null end v0,
        case when upper(name) = 'COMPATIBLE' then to_number(substr(value, instr(value, '.',1,1)+1, instr(value, '.',1,2)-instr(value, '.',1,1)-1)) else null end v1
    into v0, v1
    from v$parameter
    where upper(name) =  'COMPATIBLE';
    if v0 < <%=odiRef.getOption( "COMPATIBLE" )%> then
        raise_application_error(-20101, 'ODIKM-ORA-10000: You are using RDBMS version '||v0||'.'||v1||'. This version does not support IKM COMPATIBLE= <%=odiRef.getOption( "COMPATIBLE" )%>');
    end if;
end;

triggerCmd = """ create or replace trigger <%=odiRef.getJrnInfo("JRN_FULL_TRIGGER")%> after insert or update or delete on <%=odiRef.getJrnInfo("FULL_TABLE_NAME")%> for each row declare V_FLAG VARCHAR(1); <%=odiRef.getColList("", "V_[COL_NAME]\t[DEST_CRE_DT];", "\n\t", "", "PK")%> begin if inserting then <%=odiRef.getColList("", "V_[COL_NAME] := :new.[COL_NAME];", "\n\t\t", "", "PK")%> V_FLAG := 'I'; end if;
if updating then <%=odiRef.getColList("", "V_[COL_NAME] := :new.[COL_NAME];", "\n\t\t", "", "PK")%> V_FLAG := 'I'; end if;
if deleting then <%=odiRef.getColList("", "V_[COL_NAME] := :old.[COL_NAME];", "\n\t\t", "", "PK")%> V_FLAG := 'D'; end if;
insert into <%=odiRef.getJrnInfo("JRN_FULL_NAME")%> ( JRN_SUBSCRIBER, JRN_CONSUMED, JRN_FLAG, JRN_DATE, <%=odiRef.getColList("", "[COL_NAME]", ",\n\t\t", "", "PK")%> ) select JRN_SUBSCRIBER, '0', V_FLAG, sysdate, <%=odiRef.getColList("", "V_[COL_NAME]", ",\n\t\t", "", "PK")%> from <%=odiRef.getJrnInfo("SNP_JRN_SUBSCRIBER")%> where JRN_TNAME = '<%=odiRef.getJrnInfo("FULL_TABLE_NAME")%>' /* The following line can be uncommented for symetric replication */ /* and upper(USER) <> upper('<%=odiRef.getInfo("DEST_USER_NAME")%>') */ ; end; """
# Create the statement myStmt = myCon.createStatement()
# Execute the trigger creation myStmt.execute(triggerCmd)
myStmt.close() myStmt = None
# Commit, just in case myCon.commit()

# Validating KM options
<%

/* Validate COMPATIBLE */
if (!(
	"7".equals( odiRef.getOption ("COMPATIBLE") )  ||
	"8".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"9".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"10".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"11".equals( odiRef.getOption ("COMPATIBLE") ) ||
	"12".equals( odiRef.getOption ("COMPATIBLE") )
))  {
	%>raise OdiKMException("ODIKM-STDKM-10000", "ODIKM-STDKM-10000: Invalid value \"{0}\" for option \"COMPATIBLE\"",["<%=odiRef.getOption ("COMPATIBLE")%>"])<%
};

%>

DECLARE -- Validating KM options

<% if (odiRef.getOption("ENABLE_EDITION_SUPPORT").equals("1")) {  %>	editionsEnabled CHAR(1);	/* For Edition support */ <%};%>
	dbVersion1	NUMBER(2,0);
 	dbVersion2	NUMBER(2,0); 

BEGIN 

<% if (!( "9".equals( odiRef.getOption ("COMPATIBLE") ) || 
	"10".equals( odiRef.getOption ("COMPATIBLE") ) || 
	"11".equals( odiRef.getOption ("COMPATIBLE") ) || 
	"12".equals( odiRef.getOption ("COMPATIBLE") ) ))  { %> 

	-- Validate COMPATIBLE option
	raise_application_error(-20101, 'ODIKM-STDKM-10000: Invalid value "<%=odiRef.getOption ("COMPATIBLE")%>" for option "COMPATIBLE"');
<% };  %>	

	-- Verify RDBMS version 
	select 
		case when upper(name) = 'COMPATIBLE' then to_number(substr(value, 1, instr(value, '.',1,1)-1)) else null end v0, 
		case when upper(name) = 'COMPATIBLE' then to_number(substr(value, instr(value, '.',1,1)+1, instr(value, '.',1,2)-instr(value, '.',1,1)-1)) else null end v1 
	into	dbVersion1, dbVersion2 
	from	v$parameter 
	where	upper(name) =  'COMPATIBLE'; 

 	IF dbVersion1 < <%=odiRef.getOption( "COMPATIBLE" )%> THEN 
		raise_application_error(-20101, 'ODIKM-ORA-10000: You are using RDBMS version '||dbVersion1||'.'||dbVersion2||'. This version does not support COMPATIBLE= <%=odiRef.getOption( "COMPATIBLE" )%>.'); 
	END IF;  


<% if (odiRef.getOption("ENABLE_EDITION_SUPPORT").equals("1")) {   /* For Edition support */ %> 

	-- Make sure editions are enabled for <%=odiRef.getInfo("DEST_SCHEMA")%> 
	select	EDITIONS_ENABLED 
	into	editionsEnabled 
	from	DBA_USERS 
	where	USERNAME	= '<%=odiRef.getInfo("DEST_SCHEMA")%>'; 

 	IF editionsEnabled = 'N' THEN 	
		raise_application_error(-20101, 'ODIKM-ORA-10001: Editions are not enabled for user <%=odiRef.getInfo("DEST_SCHEMA")%>. This is required for edition support. Please use ALTER USER <%=odiRef.getInfo("DEST_SCHEMA")%> ENABLE EDITIONS.');
        END IF;   

	-- Make sure editions are enabled for <%=odiRef.getInfo("DEST_WORK_SCHEMA")%> 
	select	EDITIONS_ENABLED 
	into	editionsEnabled 
	from	DBA_USERS 
	where	USERNAME	= '<%=odiRef.getInfo("DEST_WORK_SCHEMA")%>'; 

 	IF editionsEnabled = 'N' THEN 	
		raise_application_error(-20101, 'ODIKM-ORA-10001: Editions are not enabled for user <%=odiRef.getInfo("DEST_WORK_SCHEMA")%>. This is required for edition support. Please use ALTER USER <%=odiRef.getInfo("DEST_WORK_SCHEMA")%> ENABLE EDITIONS.'); 
	END IF;

	-- Make sure editions are enabled for <%=odiRef.getInfo("DEST_DEFW_SCHEMA")%> 
	select	EDITIONS_ENABLED 
	into	editionsEnabled 
	from	DBA_USERS 
	where	USERNAME = '<%=odiRef.getInfo("DEST_DEFW_SCHEMA")%>'; 

 	IF editionsEnabled = 'N' THEN 	
		raise_application_error(-20101, 'ODIKM-ORA-10001: Editions are not enabled for user <%=odiRef.getInfo("DEST_DEFW_SCHEMA")%>. This is required for edition support. Please use ALTER USER <%=odiRef.getInfo("DEST_DEFW_SCHEMA")%> ENABLE EDITIONS.'); 
	END IF; 

<% }; %>  

END;

begin

begin 
execute immediate ' ALTER TABLE <%=odiRef.getTable("L","ERR_NAME", "W")%> ADD (ODI_PK <%=odiRef.getDataType("DEST_VARCHAR", "32", "")%>, ODI_SESS_NO <%=odiRef.getDataType("DEST_NUMERIC", "19", "")%>)';
exception when others then null; end;

begin 
execute immediate ' update <%=odiRef.getTable("L","ERR_NAME", "W")%>  set ODI_PK = SYS_GUID()';
exception when others then null; end;

begin 
execute immediate ' alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> add constraint PK_ODI_PK primary key (ODI_PK)';
exception when others then null; end;

end;

begin

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN ROW_ID  TO ODI_ROW_ID';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN ERR_TYPE  TO ODI_ERR_TYPE';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN ERR_MESS  TO ODI_ERR_MESS';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN CHECK_DATE  TO ODI_CHECK_DATE';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN ORIGIN  TO ODI_ORIGIN';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN CONS_NAME  TO ODI_CONS_NAME';
exception when others then null;
end;

begin
execute immediate 'alter table <%=odiRef.getTable("L","ERR_NAME", "W")%> RENAME COLUMN CONS_TYPE  TO ODI_CONS_TYPE';
exception when others then null;
end;


end;
